int logfmt_parse(const char *in, char *key_out, size_t k_sz, char *val_out, size_t v_sz) {
    const char *eq = strchr(in, '=');
    if (!eq) return -1;
    size_t klen = (size_t)(eq - in);
    if (klen >= k_sz) klen = k_sz - 1;
    strncpy(key_out, in, klen);
    key_out[klen] = '\0';

    const char *val_start = eq + 1;
    while (*val_start && isspace(*val_start)) val_start++;

    if (*val_start == '"') {
        const char *quote_end = strchr(val_start + 1, '"');
        if (quote_end) {
            size_t vlen = (size_t)(quote_end - val_start) - 1;
            if (vlen >= v_sz) vlen = v_sz - 1;
            strncpy(val_out, val_start + 1, vlen);
            val_out[vlen] = '\0';
        } else {
            return -1;
        }
    } else {
        const char *val_end = strchr(val_start, ' ');
        if (!val_end) val_end = strchr(val_start, '\0');
        size_t vlen = (size_t)(val_end - val_start);
        if (vlen >= v_sz) vlen = v_sz - 1;
        strncpy(val_out, val_start, vlen);
        val_out[vlen] = '\0';
    }

    return 0;
}

