int logfmt_append(char *buf, size_t buf_sz, const char *key, const char *val) {
    size_t len = strlen(buf);
    if (len >= buf_sz || buf[len - 1] != '\0') return -1;

    int n = snprintf(buf + len, buf_sz - len, "%s=%s", key, val);
    if (n <= 0 || (size_t)n >= buf_sz - len) return -1;

    buf[len + n] = '\0';
